import assert from 'node:assert/strict';
import {LivingSwarm} from './living.js';import {OrganismSwarm} from './organism_swarm.js';import {SwarmKlein} from './klein_bridge.js';import {MessyWorld} from './messy_world.js';
import {GameEngineMorph,initialGameState,executeGameDescendant,engineActions} from './gameenginex_morph.js';
const S=new LivingSwarm({seed:3});for(let i=0;i<24;i++)S.add({gate:i+1,line:i%6+1,color:i%6+1,tone:i%6+1,base:i%5+1,dimension:['Movement','Evolution','Being','Design'][i%4]},'person',.3+(i%6)*.03,.3+Math.floor(i/6)*.03);const O=new OrganismSwarm(S);for(let i=0;i<5;i++)O.step();
const K=new SwarmKlein(),M=new MessyWorld(),G=new GameEngineMorph(O,K,M);const actions=engineActions();
const constraints=[{path:['position','x'],equals:1},{path:['drives','creation'],minimum:.69}];
const cases=[{initial:{drives:{creation:.5}},constraints},{initial:{position:{z:4},drives:{creation:.5}},constraints}];
const r=G.develop({name:'external two-condition objective',cases,actions});console.log(r.steps.map(s=>s.step+(s.plan?": "+s.plan.join(" → "):"")).join("\n"));assert.equal(r.ok,true);assert.equal(r.integrated,true);assert.equal(r.steps.find(s=>s.step==='construct').by,'units');assert.ok(r.record.tree.plan.length>=2);assert.equal(r.steps.find(s=>s.step==='extract').checkWithSwarmGone,1);assert.equal(S.units.filter(u=>u.role).length,0);assert.ok(K.stats().events>0);assert.ok(M.query({p:'operation'}).length>0);
const record=JSON.parse(JSON.stringify(G.export()))[0];const state=initialGameState();state.position.z=7;const trace=[];const out=executeGameDescendant(record,state,trace);assert.equal(out.position.x,1);assert.ok(out.drives.creation>=.69);assert.equal(out.position.z,7);console.log('PASS: native units composed '+r.record.tree.plan.map(s=>s.op).join(' → ')+'; both cases and independent serialized descendant on a third initial state passed; Klein and MESSY observed actual transitions.');

const S2=new LivingSwarm({seed:4});for(let i=0;i<24;i++)S2.add({gate:i+1,line:i%6+1,color:i%6+1,tone:i%6+1,base:i%5+1,dimension:['Movement','Evolution','Being','Design'][i%4]},'person',.3+(i%6)*.03,.3+Math.floor(i/6)*.03);const O2=new OrganismSwarm(S2);for(let i=0;i<5;i++)O2.step();const G2=new GameEngineMorph(O2,new SwarmKlein(),new MessyWorld());G2.import(JSON.parse(JSON.stringify(G.export())));const rr=G2.develop({name:'new environment',cases:[{initial:{position:{z:9}},constraints}],actions});assert.equal(rr.integrated,true);assert.equal(rr.steps.find(s=>s.step==='construct').recalled,true);assert.equal(rr.results[0].state.position.z,9);console.log('PASS: fresh organism imported and recalled the learned formation; verified clone on new state.');
